import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(bytes32 hash) public {
        // Deal 1 ether to the test contract for the constructor call
        vm.deal(address(this), 1 ether);
        c = new C{value: 1 ether}();

        // Set up an actor with 1 ether to call lockInGuess
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.lockInGuess{value: 1 ether}(hash);

