pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 guess, uint256 rollN, address actor) public {
        // Keep actor distinct and able to pay; restrict rollN to be after block 1
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(rollN > 1);
        vm.roll(rollN);

        // Fund actor and make them lock in a guess with exactly 1 ether
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // Advance by exactly 1 block so settle should be possible for P but not for M.
        // (M stores block.number+2, so its settle requires block.number > (rollN+2), not yet true.)
        vm.roll(rollN + 1);
        vm.prank(actor);
        (bool ok,) = address(c).call(abi.encodeWithSignature("settle()"));
        // If settle executed with the wrong block (the current+2 after the lock, 
        // which is unavailable because we only advanced 1 block), it would revert.
        // The correct contract uses current+1 which is exactly rollN+1, whose 
        // block hash is available and allows settle to proceed (no guarantee on guess 
        // correctness, but call must not revert due to block number).
        assertTrue(ok);
    }
}

