pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 guessHash) public {
        // 1. Setup: deploy adversarial helper that captures the caller's balance change
        SettleHelper helper = new SettleHelper(c);
        vm.deal(address(helper), 1 ether);

        // 2. Helper locks a guess
        helper.lockInGuess(guessHash);

        // 3. Wait until the guess block is settled
        vm.roll(block.number + 2);

        // 4. Capture helper's balance before settle
        uint256 balanceBefore = address(helper).balance;

        // 5. Helper settles
        helper.settle();

        // 6. Assert: if the guess was correct, helper's balance must have increased by exactly 2 ether
        //          If incorrect, balance remains unchanged (increase 0). The fuzzer will try many guessHash values.
        uint256 balanceAfter = address(helper).balance;
        uint256 increase = balanceAfter - balanceBefore;

        // The reference contract always pays exactly 2 ether on correct guess, 0 otherwise.
        // The bug pays 1 ether on correct guess, 0 otherwise.
        // Thus, for any input, the increase is never 1 ether in the reference, but can be 1 ether in the bug.
        assertTrue(increase != 1 ether);
    }
}

contract SettleHelper {
    C c;
    constructor(C _c) {
        c = _c;
    }
    function lockInGuess(bytes32 hash) public payable {
        c.lockInGuess{value: msg.value}(hash);
    }
    function settle() public {
        c.settle();
    }
    receive() external payable {}
}

