pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        vm.deal(address(this), 2 ether);
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(uint256 blockOffset, uint8 guessNonce) public {
        // Keep blockOffset small to avoid excessive block warping
        blockOffset = bound(blockOffset, 1, 256);

        // Deploy a guesser actor and fund it with 1 ether for lockInGuess
        address guesser = address(uint160(guessNonce) + 0x10000);
        vm.deal(guesser, 1 ether);

        // The guesser locks in a hash that will NOT match the future blockhash,
        // producing a wrong guess in general.
        bytes32 wrongHash = keccak256(abi.encodePacked(uint8(0)));
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(wrongHash);

        // Warp past the settlement block
        vm.roll(block.number + blockOffset);

        // Record balance before settle
        uint256 balanceBefore = address(c).balance;

        // Prank the guesser to settle
        vm.prank(guesser);
        c.settle();

        uint256 balanceAfter = address(c).balance;

        // INVARIANT: The contract balance must be >= 1 ether after settling a wrong guess.
        // The reference version keeps 2 ether (does not pay out), the buggy version pays out 2 ether
        // leaving only 1 ether remaining, but never less than 1 ether. However, because the guess is wrong,
        // the correct contract balance stays exactly 2 ether (initial 1 + lock 1), while the buggy contract
        // balance becomes 0 ether, violating balance >= 1 ether.
        // Strictly:  balanceAfter >= 1 ether holds for the reference, but the buggy version can produce 0 ether.
        assertTrue(balanceAfter >= 1 ether);
    }
}

