    function testFuzz_property(uint256 blockNumber, bytes32 guessHash) public {
        // Constrain to admissible domain
        vm.assume(blockNumber > 0 && blockNumber < type(uint256).max);
        vm.assume(guessHash != bytes32(0));

        // Deploy reentrant attacker
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), 1 ether);

        // Fund c with 2 ether for prize payout
        vm.deal(address(c), 2 ether);

        // Attacker locks in guess
        vm.prank(address(attacker));
        c.lockInGuess{value: 1 ether}(guessHash);

        // Warp to block after guess block
        vm.roll(blockNumber);

        // Determine the answer at guessed block
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        // If guess is correct, attacker's receive() will re-enter settle()
        // Otherwise, single settle proceeds normally
        vm.prank(address(attacker));
        attacker.attack();

        // General rule: after settle() completes, the caller's guess block is always 0
        // Bug: mutant resets block after transfer, so reentrant call can double-claim,
        // leaving block non-zero or draining contract
        (uint256 storedBlock,) = c.guesses(address(attacker));
        assertTrue(storedBlock == 0);
    }
}

contract Attacker {
    C public target;
    uint256 public reentries;

    constructor(C _target) {
        target = _target;
    }

    function attack() external {
        reentries = 0;
        target.settle();
    }

    receive() external payable {
        if (reentries < 1 && address(target).balance >= 2 ether) {
            reentries++;
            target.settle();
        }
    }
}

