pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 blockNumber, bytes32 guess, uint256 reEntryAttempts) public {
        // bound to admissible domain: blockNumber must be >0 and <= a future block after setup
        vm.assume(blockNumber > 0 && blockNumber <= type(uint256).max - 1000);
        vm.assume(reEntryAttempts > 0 && reEntryAttempts <= 5);

        // deploy a re-entrant attacker that will call settle() again when receiving ETH
        ReentrantAttacker attacker = new ReentrantAttacker(c, reEntryAttempts);

        // fund attacker with enough ether for repeated lockInGuess calls
        vm.deal(address(attacker), (reEntryAttempts + 1) * 1 ether + 1 ether);

        // attacker locks in a guess for each potential re-entry pass
        vm.startPrank(address(attacker));
        for (uint256 i = 0; i <= reEntryAttempts; i++) {
            c.lockInGuess{value: 1 ether}(guess);
        }
        vm.stopPrank();

        // move to the block after lockInGuess
        vm.roll(blockNumber + 1);

        // make blockhash deterministic for testing
        vm.assume(blockhash(blockNumber) == keccak256(abi.encodePacked(guess)));

        // attacker triggers settle
        vm.prank(address(attacker));
        c.settle();

        // after settle completes (no reverted), the attacker's block in mapping must be reset to 0
        // access via the auto-generated getter for the mapping
        (uint256 storedBlock, ) = c.guesses(address(attacker));
        assertTrue(storedBlock == 0);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 reEntryCount;
    uint256 maxReEntries;

    constructor(C _target, uint256 _maxReEntries) {
        target = _target;
        maxReEntries = _maxReEntries;
    }

    receive() external payable {
        if (reEntryCount < maxReEntries) {
            reEntryCount++;
            target.settle();
        }
    }
}
